import{_ as a,o as i,c as d,a8 as l}from"./chunks/framework.CiGKN4gy.js";const b=JSON.parse('{"title":"Embedded Variables","description":"","frontmatter":{"title":"Embedded Variables","lang":"en"},"headers":[],"relativePath":"advance/variable.md","filePath":"advance/variable.md","lastUpdated":1790354326000}'),o={name:"advance/variable.md"};function t(c,e,r,s,n,h){return i(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjJFbWJlZGRlZCUyMFZhcmlhYmxlcyUyMiUyQyUyMmxhbmclMjIlM0ElMjJlbiUyMiUyQyUyMmRhdGUlMjIlM0ExNzkwMzU0MzI2MDAwJTdE"},[...e[0]||(e[0]=[l('<h1 id="embedded-variables" tabindex="-1">Embedded Variables <a class="header-anchor" href="#embedded-variables" aria-label="Permalink to &quot;Embedded Variables&quot;">​</a></h1><p>When writing <code>nginx.conf</code>, some variables are inevitably needed. For example, <code>$remote_addr</code> can be used to get the client IP address.</p><p>This module adds several available variables.</p><div class="warning custom-block"><p class="custom-block-title">CAN NOT BE USED FOR DIRECTIVE <code>if</code></p><p>See <a href="/ngx_waf-docs/guide/faq.html#embedded-variables-and-directive-if">FAQ</a>.</p></div><h2 id="waf-log" tabindex="-1"><code>$waf_log</code> <a class="header-anchor" href="#waf-log" aria-label="Permalink to &quot;`$waf_log`&quot;">​</a></h2><p>Not an empty string if the firewall is checked in this request, otherwise an empty string. This variable is mainly used in the directive <code>access_log</code>, see <a href="./log.html#customised-log-format">Customised Log Format</a>.</p><h2 id="waf-blocking-log" tabindex="-1"><code>$waf_blocking_log</code> <a class="header-anchor" href="#waf-blocking-log" aria-label="Permalink to &quot;`$waf_blocking_log`&quot;">​</a></h2><p>Not an empty string if this request was originally blocked by the module, and vice versa. This variable is mainly used in the directive <code>access_log</code>, see <a href="./log.html#customised-log-format">Customised Log Format</a>.</p><h2 id="waf-blocked" tabindex="-1"><code>$waf_blocked</code> <a class="header-anchor" href="#waf-blocked" aria-label="Permalink to &quot;`$waf_blocked`&quot;">​</a></h2><p>Whether this request is intercepted by this module, if intercepted, its value is <code>&#39;true&#39;</code>, otherwise it is <code>&#39;false&#39;</code>.</p><h2 id="waf-spend" tabindex="-1"><code>$waf_spend</code> <a class="header-anchor" href="#waf-spend" aria-label="Permalink to &quot;`$waf_spend`&quot;">​</a></h2><p>Indicates how much time (in milliseconds) this check took, retaining 5 decimal places, with rounding rules depending on the specific C standard library implementation.</p><h2 id="waf-rule-type" tabindex="-1"><code>$waf_rule_type</code> <a class="header-anchor" href="#waf-rule-type" aria-label="Permalink to &quot;`$waf_rule_type`&quot;">​</a></h2><p>If a black and white list rule is in effect for this request, the value is the type of rule that triggered it. Here are the possible values. If no black and white list rule is in effect then the value is <code>&#39;&#39;</code>.</p><ul><li><code>&#39;CC-DENY&#39;</code></li><li><code>&#39;WHITE-IPV4&#39;</code></li><li><code>&#39;WHITE-IPV6&#39;</code></li><li><code>&#39;BLACK-IPV4&#39;</code></li><li><code>&#39;BLACK-IPV6&#39;</code></li><li><code>&#39;WHITE-URL&#39;</code></li><li><code>&#39;BLACK-URL&#39;</code></li><li><code>&#39;BLACK-ARGS&#39;</code></li><li><code>&#39;BLACK-USER-AGENT&#39;</code></li><li><code>&#39;WHITE-REFERER&#39;</code></li><li><code>&#39;BLACK-REFERER&#39;</code></li><li><code>&#39;BLACK-COOKIE&#39;</code></li><li><code>&#39;BLACK-POST&#39;</code></li><li><code>&#39;UNDER-ATTACK&#39;</code></li><li><code>&#39;FAKE-BOT&#39;</code></li><li><code>&#39;CAPTCHA&#39;</code></li></ul><h2 id="waf-rule-details" tabindex="-1"><code>$waf_rule_details</code> <a class="header-anchor" href="#waf-rule-details" aria-label="Permalink to &quot;`$waf_rule_details`&quot;">​</a></h2><p>If this request is blocked by this module, its value is the content of the specific rule triggered. If it is not blocked, its value is <code>&#39;&#39;</code>.</p><h2 id="waf-rate" tabindex="-1"><code>$waf_rate</code> <a class="header-anchor" href="#waf-rate" aria-label="Permalink to &quot;`$waf_rate`&quot;">​</a></h2><p>An integer that represents the number of accesses to the current IP in a cycle.</p>',19)])])}const u=a(o,[["render",t]]);export{b as __pageData,u as default};
